// ── ADR 0011: grok's session ships whole, refresh token included ───────────────

const grokSessionRow = { id: "grok", installed: true, state: "authenticated", source: "session" }
const grokFile = (expires_at) =>
  JSON.stringify({
    "https://auth.x.ai::b1a00492-cli": {
      key: "eyJ-grok-access-token",
      auth_mode: "oidc",
      refresh_token: "[REDACTED]",
      expires_at,
    },
  })

test("a grok session is a POINTER whose payload is the file VERBATIM", () => {
  const exp = new Date(Date.now() + 3 * 3600e3).toISOString()
  const plan = buildPlan([grokSessionRow], { readText: () => grokFile(exp) })
  assert.equal(plan.entries.length, 1)
  const e = plan.entries[0]
  assert.equal(e.kind, "session")
  assert.equal(e.boxVar, "GROK_AUTH_JSON")
  assert.equal(e.path, "~/.grok/auth.json")
  assert.equal(e.supersedes, "XAI_API_KEY")
  assert.equal(e.expires, exp)
  // The pointer rule still holds: auth.toml itself carries NO credential — the
  // refresh token travels at box-create time, not through the generated file.
  const body = renderAuthToml(plan)
  assert.ok(!body.includes("grok-rt-REAL"), "refresh token leaked into auth.toml")
  assert.match(body, /\[templates\.grok\.session\]/)
})

test("a grok file with no live oidc entry is a gap, not a guess", () => {
  // An api_key-style config, an empty map, a missing refresh half, an unreadable
  // expiry — none of them are a session, and none of them may be shipped as one.
  for (const text of [
    "{}",
    JSON.stringify({ "x::y": { auth_mode: "apikey", key: "k" } }),
    JSON.stringify({ "x::y": { auth_mode: "oidc", key: "k" } }),
    JSON.stringify({ "x::y": { auth_mode: "oidc", key: "not-a-jwt", refresh_token: "rt", expires_at: "garbage" } }),
    "not json",
  ]) {
    const plan = buildPlan([grokSessionRow], { readText: () => text })
    assert.equal(plan.entries.length, 0, `shipped a session out of: ${text}`)
    assert.equal(plan.gaps.length, 1)
  }
})

import test from "node:test"
import assert from "node:assert/strict"
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import path from "node:path"
import { spawnSync } from "node:child_process"
import { fileURLToPath } from "node:url"
import { formatRefresh, refreshExitCode, refreshRows, rotateCodexChain } from "../src/auth-refresh.js"
import { connectionMaterial, readOauthSecret, saveConnection } from "../src/connections.js"

const ROOT = fileURLToPath(new URL("..", import.meta.url))
const TOKEN = [REDACTED]"fabricated-token-".repeat(4)}`
const NOW = Date.parse("2026-09-11T12:00:00Z")
const DAY = 86400000

const iso = (offsetMs) => new Date(NOW + offsetMs).toISOString()
// A bearer whose only readable claim is `exp`; the reader never verifies it.
const jwt = (expiresAt) => `x.${Buffer.from(JSON.stringify({ exp: Math.floor(Date.parse(expiresAt) / 1000) })).toString("base64url")}.y`
const codexFile = (expiresAt) => JSON.stringify({ auth_mode: "chatgpt", tokens: { access_token: [REDACTED], refresh_token: "[REDACTED]" } })
const grokFile = (expiresAt) => JSON.stringify({ default: { auth_mode: "oidc", key: jwt(expiresAt), refresh_token: "[REDACTED]", expires_at: expiresAt } })
const codexOauth = (id, expiresAt, directory) => saveConnection({ id, harness: "codex", method: "oauth" },
  { auth_mode: "chatgpt", tokens: { access_token: [REDACTED], refresh_token: [REDACTED]}` } }, { directory })

function fixture(t) {
  const directory = mkdtempSync(path.join(tmpdir(), "e2b-refresh-"))
  t.after(() => rmSync(directory, { recursive: true, force: true }))
  return directory
}

test("bare refresh covers every connection and session, sorted, and only stale rows fail the exit code", async (t) => {
  const directory = fixture(t)
  const fresh = saveConnection({ id: "claude-work", harness: "claude", method: "setup-token", expiresAt: iso(300 * DAY) }, TOKEN, { directory })
  const soon = saveConnection({ id: "claude-personal", harness: "claude", method: "setup-token", expiresAt: iso(10 * DAY) }, TOKEN, { directory })
  const pasted = saveConnection({ id: "claude-pasted", harness: "claude", method: "setup-token", expiresAt: null }, TOKEN, { directory })
  const codex = saveConnection({ id: "codex-personal", harness: "codex", method: "borrowed-session", path: "/fixture/codex/auth.json" }, undefined, { directory })
  const muse = saveConnection({ id: "muse-personal", harness: "muse", method: "oauth" }, { kind: "api-key", META_API_KEY: "muse-key" }, { directory })
  const files = {
    "/fixture/codex/auth.json": codexFile(iso(-1 * DAY)),
    "~/.grok/auth.json": grokFile(iso(5 * 3600000)),
  }
  const cfg = {
    connections: [codex, fresh, soon, pasted, muse], connectionsDir: directory,
    envSession: { grok: { var: "GROK_AUTH_JSON", path: "~/.grok/auth.json", harness: "grok" }, codex: { var: "CODEX_AUTH_JSON", path: "/fixture/codex/auth.json", harness: "codex" } },
  }
  const rotate = async () => { throw new Error("must not rotate anything here") }
  const rows = await refreshRows(cfg, { readFile: (p) => files[p] ?? null, now: NOW, rotate })
  assert.deepEqual(rows.map((r) => [r.id, r.kind, r.status]), [
    ["claude-pasted", "connection", "unknown"],
    ["claude-personal", "connection", "expiring"],
    ["claude-work", "connection", "fresh"],
    ["codex-personal", "connection", "expired"],
    ["muse-personal", "connection", "fresh"],
    ["codex", "session", "expired"],
    ["grok", "session", "fresh"],
  ])
  assert.match(rows[1].action, /auth reconnect claude-personal/)
  assert.match(rows[3].action, /codex.*auth reconnect codex-personal/)
  assert.equal(rows[4].remaining, "no expiry (API key)")
  assert.match(rows[5].action, /codex login/)
  assert.equal(rows[6].remaining, "expires in 5 hours")
  assert.equal(refreshExitCode(rows), 1)
  assert.equal(refreshExitCode(rows.filter((r) => !["codex-personal", "codex"].includes(r.id))), 0)
  const text = formatRefresh(rows)
  assert.match(text, /^ROW\s+AGENT\s+KIND\s+STATUS\s+EXPIRES/)
  assert.match(text, /Nothing was changed/)
  assert.ok(!text.includes(TOKEN) && !text.includes("muse-key") && !JSON.stringify(rows).includes(TOKEN), "a report never carries a credential")
})

test("a plugin-owned codex chain is rotated only inside its last five days or when expired, and a dead chain points at reconnect", async (t) => {
  const directory = fixture(t)
  const young = codexOauth("codex-young", iso(8 * DAY), directory)
  const aging = codexOauth("codex-aging", iso(2 * DAY), directory)
  const dead = codexOauth("codex-dead", iso(-1 * DAY), directory)
  const rotated = []
  const rotate = async (record, dir) => {
    rotated.push(record.id)
    if (record.id === "codex-dead") throw new Error("codex refresh failed (400: invalid_grant) - sign in again with auth reconnect")
    // Real rotation is codexRefresh + rewriteOauthSecret; the row must reflect the rewritten secret.
    const body = JSON.stringify({ access_token: jwt(iso(10 * DAY)), refresh_token: "next" })
    await rotateCodexChain(record, dir, { fetch: async () => ({ ok: true, status: 200, text: async () => body }), now: () => NOW })
  }
  const rows = await refreshRows({ connections: [young, aging, dead], connectionsDir: directory }, { now: NOW, rotate })
  assert.deepEqual(rotated, ["codex-aging", "codex-dead"], "young chain left alone")
  const byId = Object.fromEntries(rows.map((r) => [r.id, r]))
  assert.equal(byId["codex-young"].status, "fresh")
  assert.equal(byId["codex-young"].rotated, undefined)
  assert.equal(byId["codex-aging"].rotated, true)
  assert.equal(byId["codex-aging"].remaining, "expires in 10 days")
  assert.equal(readOauthSecret(aging, directory).tokens.refresh_token, "next", "the secret file carries the new chain")
  assert.equal(byId["codex-dead"].status, "expired")
  assert.equal(byId["codex-dead"].rotated, false)
  assert.match(byId["codex-dead"].action, /invalid_grant.*auth reconnect codex-dead/)
  assert.equal(refreshExitCode(rows), 1)
  const text = formatRefresh(rows)
  assert.match(text, /codex-aging .* rotated /)
  assert.match(text, /Rotated 1 plugin-owned codex chain\./)
  assert.ok(!text.includes("refresh-") && !JSON.stringify(rows).includes("refresh-"), "no refresh token in the table or the JSON")
  assert.equal(connectionMaterial(aging, { directory, now: NOW }).expiresAt, iso(10 * DAY))
})

test("an ID narrows to one row, an unknown ID is an error, and opt-out is not stale", async (t) => {
  const directory = fixture(t)
  const files = { "~/.grok/auth.json": grokFile(iso(5 * 3600000)) }
  const cfg = { connections: [], connectionsDir: directory,
    envSession: { grok: { var: "GROK_AUTH_JSON", path: "~/.grok/auth.json", harness: "grok" } }, templatePrefer: { grok: "env" } }
  const [row] = await refreshRows(cfg, { id: "grok", readFile: (p) => files[p] ?? null, now: NOW })
  assert.equal(row.status, "opted-out")
  assert.equal(refreshExitCode([row]), 0)
  await assert.rejects(refreshRows(cfg, { id: "nope", readFile: () => null, now: NOW }), /Unknown connection or session 'nope'/)
  const missing = await refreshRows({ ...cfg, templatePrefer: {} }, { readFile: () => null, now: NOW })
  assert.equal(missing[0].status, "unavailable")
  assert.equal(refreshExitCode(missing), 1)
})

test("CLI: auth refresh takes no ID or one, rejects extras, and exits 1 on a stale row", (t) => {
  const root = fixture(t)
  mkdirSync(path.join(root, "state"), { recursive: true })
  const env = { ...process.env, HERDR_PLUGIN_CONFIG_DIR: root, HERDR_PLUGIN_STATE_DIR: path.join(root, "state"), HERDR_PLUGIN_CONTEXT_JSON: "", E2B_API_KEY: "", E2B_DOMAIN: "" }
  const cli = (args) => spawnSync(path.join(ROOT, "bin/e2b-box"), args, { env, encoding: "utf8", timeout: 15000 })
  const empty = cli(["auth", "refresh"])
  assert.equal(empty.status, 0, empty.stderr)
  assert.match(empty.stdout, /Nothing to refresh/)
  const directory = path.join(root, "connections")
  saveConnection({ id: "claude-old", harness: "claude", method: "setup-token", expiresAt: iso(-1 * DAY) }, TOKEN, { directory })
  const stale = cli(["auth", "refresh", "--json"])
  assert.equal(stale.status, 1)
  const [row] = JSON.parse(stale.stdout)
  assert.equal(row.status, "expired")
  assert.ok(!stale.stdout.includes(TOKEN))
  assert.equal(cli(["auth", "refresh", "claude-old"]).status, 1)
  assert.match(cli(["auth", "refresh", "nope"]).stderr, /Unknown connection or session/)
  assert.match(cli(["auth", "refresh", "a", "b"]).stderr, /Unexpected or missing argument/)
  assert.match(cli(["auth", "refresh", "--yes"]).stderr, /not supported by auth refresh/)
})

import test from "node:test"
import assert from "node:assert/strict"
import { formatBoxAuthNote, formatFleetAuthWarning, unauthenticatedMembers } from "../src/fleet-auth.js"

// The question this module answers is NOT "did `e2b-box auth` find a credential"
// but "will this member's box be handed one" — the full resolveEnv ladder, because
// a member configured by hand is authenticated and warning about it would be a lie.

const member = (template, label) => ({ template, label: label || `t-1-${template}` })

// --- nothing configured ------------------------------------------------------

test("a roster with no credential anywhere warns per member, naming the BOX variable", () => {
  const gaps = unauthenticatedMembers([member("claude"), member("codex")], {}, {})
  assert.deepEqual(gaps, [
    // The variable the REMEDY produces, not the row's primary one: claude's advice
    // is `claude setup-token`, and that token authenticates nothing when it is
    // pasted into ANTHROPIC_API_KEY.
    { label: "t-1-claude", template: "claude", boxVar: "CLAUDE_CODE_OAUTH_TOKEN" },
    // Not CODEX_API_KEY: the variable a box needs is not the one this machine is
    // searched under, and they differ for three of the seven harnesses.
    { label: "t-1-codex", template: "codex", boxVar: "OPENAI_API_KEY" },
  ])
})

test("a template no harness ships is never warned about", () => {
  // `base` is a plain image with no agent in it, and `mine` is somebody's own
  // template. Neither has a credential to be missing, and the plugin never guesses
  // a variable name for a row that is not in the table.
  assert.deepEqual(unauthenticatedMembers([member("base"), member("mine")], {}, {}), [])
})

// --- every rung of the ladder counts -----------------------------------------

test("a value discovered by `e2b-box auth` authenticates the member", () => {
  const cfg = { envDiscovered: { claude: { ANTHROPIC_API_KEY: "sk-ant-x" } } }
  assert.deepEqual(unauthenticatedMembers([member("claude")], cfg, {}), [])
})

test("opencode's auth.json pointer authenticates the member (its boxVar has no host variable)", () => {
  // opencode forwards a whole auth.json under OPENCODE_AUTH_CONTENT and has no
  // `hostVar`, so the row's own `boxVar` must count: a member that came up signed
  // in was being named as unauthenticated (fleet test, 2026-09-08).
  const cfg = { envDiscovered: { opencode: { OPENCODE_AUTH_CONTENT: '{"openrouter":{"type":"api","key":"k"}}' } } }
  assert.deepEqual(unauthenticatedMembers([{ template: "opencode", label: "m" }], cfg, {}), [])
})

test("a forwarded NAME authenticates the member only when this shell holds it", () => {
  const cfg = { envForward: { claude: { ANTHROPIC_API_KEY: "[REDACTED]" } } }
  assert.deepEqual(unauthenticatedMembers([member("claude")], cfg, { ANTHROPIC_API_KEY: "sk-ant-x" }), [])
  // Recorded in auth.toml, unset here: resolveEnv injects nothing, so the box gets
  // nothing, so this is exactly the member the warning exists for.
  assert.deepEqual(unauthenticatedMembers([member("claude")], cfg, {}), [
    { label: "t-1-claude", template: "claude", boxVar: "CLAUDE_CODE_OAUTH_TOKEN" },
  ])
})

test("either of claude's two credential variables authenticates the member", () => {
  // A Console key and a subscription token are different accounts under different
  // names, and a box needs one of them, not both. Warning about a member that holds
  // the token is the false alarm that teaches people to ignore this warning.
  const token = { envByTemplate: { claude: { CLAUDE_CODE_OAUTH_TOKEN: "[REDACTED]" } } }
  assert.deepEqual(unauthenticatedMembers([member("claude")], token, {}), [])
  const key = { envByTemplate: { claude: { ANTHROPIC_API_KEY: "sk-ant-x" } } }
  assert.deepEqual(unauthenticatedMembers([member("claude")], key, {}), [])
  // A forwarded token counts too — same ladder, same two names.
  const forwarded = { envForward: { claude: { CLAUDE_CODE_OAUTH_TOKEN: "[REDACTED]" } } }
  assert.deepEqual(
    unauthenticatedMembers([member("claude")], forwarded, { CLAUDE_CODE_OAUTH_TOKEN: "[REDACTED]" }),
    [],
  )
})

test("a credential the user wrote by hand authenticates the member", () => {
  // Either of the user's own tables. This is the whole reason the check reads the
  // resolved env rather than the generated file: `[templates.<t>.env]` is the remedy
  // the warning itself prints, and printing it at somebody who already took it would
  // make the warning noise.
  const perTemplate = { envByTemplate: { claude: { ANTHROPIC_API_KEY: "sk-ant-x" } } }
  assert.deepEqual(unauthenticatedMembers([member("claude")], perTemplate, {}), [])
  const shared = { envShared: { ANTHROPIC_API_KEY: "sk-ant-x" } }
  assert.deepEqual(unauthenticatedMembers([member("claude")], shared, {}), [])
})

test("a shipped default that is not a credential does not authenticate anything", () => {
  // amp ships AMP_EXECUTOR=sandbox. A template with an env table is not a template
  // with a key, so the box variable is what gets looked at and nothing else.
  const cfg = { templateEnvDefaults: { amp: { AMP_EXECUTOR: "sandbox" } } }
  assert.deepEqual(unauthenticatedMembers([member("amp")], cfg, {}), [
    { label: "t-1-amp", template: "amp", boxVar: "AMP_API_KEY" },
  ])
})

test("a blank credential is a missing one", () => {
  // An empty key is the failure that shows up furthest from its cause: the agent
  // boots, reads it, and dies authenticating — which reads as a broken key rather
  // than an absent one.
  const cfg = { envByTemplate: { claude: { ANTHROPIC_API_KEY: "   ", CLAUDE_CODE_OAUTH_TOKEN: "" } } }
  assert.deepEqual(unauthenticatedMembers([member("claude")], cfg, {}), [
    { label: "t-1-claude", template: "claude", boxVar: "CLAUDE_CODE_OAUTH_TOKEN" },
  ])
})

// --- the single-box note -----------------------------------------------------

test("the box note names the remedy and the variable, and is silent when there is one", () => {
  const note = formatBoxAuthNote("claude", {}, {}, "/tmp/config.toml")
  assert.match(note, /sign-in screen/)
  assert.match(note, /claude setup-token/)
  assert.match(note, /CLAUDE_CODE_OAUTH_TOKEN/)
  assert.match(note, /\/tmp\/config\.toml/)
  // A box that WAS handed something says nothing — this prints on every attach, so
  // anything it says when nothing is wrong is noise the user learns to skip past.
  const cfg = { envByTemplate: { claude: { CLAUDE_CODE_OAUTH_TOKEN: "[REDACTED]" } } }
  assert.equal(formatBoxAuthNote("claude", cfg, {}, "/tmp/config.toml"), "")
  // …and so does a template with no agent in it to sign in.
  assert.equal(formatBoxAuthNote("base", {}, {}, "/tmp/config.toml"), "")
})

// --- the warning itself ------------------------------------------------------

test("the warning names each member, its template and its variable — once", () => {
  const text = formatFleetAuthWarning(
    [
      { label: "t-1-claude", template: "claude", boxVar: "ANTHROPIC_API_KEY" },
      { label: "t-1-codex", template: "codex", boxVar: "OPENAI_API_KEY" },
    ],
    "/tmp/config.toml",
  )
  for (const s of ["t-1-claude", "claude", "ANTHROPIC_API_KEY", "t-1-codex", "codex", "OPENAI_API_KEY"]) {
    assert.ok(text.includes(s), `warning omits ${s}`)
  }
  // One warning for the batch, not one per member: exactly one ⚠️ in the whole block.
  assert.equal(text.split("⚠️").length - 1, 1)
  // And it is a warning, not a refusal.
  assert.match(text, /not a refusal/)
})

test("the warning ends in a block the user can paste into their own config", () => {
  const text = formatFleetAuthWarning(
    [{ label: "t-1-codex", template: "codex", boxVar: "OPENAI_API_KEY" }],
    "/tmp/config.toml",
  )
  assert.match(text, /\[templates\.codex\.env\]\n\s*OPENAI_API_KEY = "…"/)
  assert.match(text, /\/tmp\/config\.toml/)
  // The other route out, named because it is the one that needs no lookup at all.
  assert.match(text, /e2b-box auth/)
})

test("an authenticated roster says nothing at all", () => {
  assert.equal(formatFleetAuthWarning([]), "")
})

test("a member with no agent is never warned about", () => {
  // `[fleet.agents] claude = ""` is the control arm: the pane stays a plain shell,
  // and a shell has no sign-in screen to land on. Key presence, not truthiness —
  // an UNMAPPED template runs an agent named after itself, so reading this by
  // truthiness would silence the whole roster instead of this one member.
  const cfg = { fleetAgents: { claude: "" } }
  assert.deepEqual(unauthenticatedMembers([member("claude"), member("codex")], cfg, {}), [
    { label: "t-1-codex", template: "codex", boxVar: "OPENAI_API_KEY" },
  ])
  const mapped = { fleetAgents: { claude: "claude --resume" } }
  assert.equal(unauthenticatedMembers([member("claude")], mapped, {}).length, 1)
  // Exactly empty, not trimmed-empty. bin/e2b-fleet gates the same value on
  // `[ -n "$agent_cmd" ]`, so a template mapped to " " has something typed into it,
  // and calling that member agentless here would be the one member nobody warned.
  const blank = { fleetAgents: { claude: " " } }
  assert.equal(unauthenticatedMembers([member("claude")], blank, {}).length, 1)
})

import test from "node:test"
import assert from "node:assert/strict"
import { spawnSync } from "node:child_process"
import { mkdtempSync, realpathSync, mkdirSync, writeFileSync, readFileSync, existsSync, rmSync } from "node:fs"
import os from "node:os"
import path from "node:path"
import { fileURLToPath } from "node:url"
import { authMenuActions } from "../src/auth-menu.js"
import { HARNESSES } from "../src/harnesses.js"
import { classifySubscription, saveConnection, readConnections } from "../src/connections.js"

const ROOT = fileURLToPath(new URL("..", import.meta.url))
const TOKEN = [REDACTED]"fake-menu-token-".repeat(4)}`
const REPLACEMENT = `sk-ant-oat01-${"new-menu-token-".repeat(4)}`
const DRIVER = String.raw`import os,pty,select,sys,time,json,fcntl,termios,struct,re
steps=json.loads(sys.argv[1]); pid,fd=pty.fork()
if pid==0:
 fcntl.ioctl(1,termios.TIOCSWINSZ,struct.pack('HHHH',28,100,0,0))
 os.execv(sys.argv[2],sys.argv[2:])
buf=b''; seen=b''; deadline=time.monotonic()+25; index=0; status=None
try:
 while time.monotonic()<deadline:
  if select.select([fd],[],[],.1)[0]:
   try: data=os.read(fd,65536)
   except OSError: data=b''
   if not data: break
   buf+=data; seen+=data
   plain=re.sub(rb'\x1b\[[0-?]*[ -/]*[@-~]',b'',seen)
   if index<len(steps) and steps[index]['wait'].encode() in plain:
    os.write(fd,steps[index]['send'].encode()); index+=1; seen=b''
  done,value=os.waitpid(pid,os.WNOHANG)
  if done: status=value; break
 if status is None:
  done,value=os.waitpid(pid,os.WNOHANG)
  if done: status=value
 if status is None: os.kill(pid,15); _,status=os.waitpid(pid,0)
 print(json.dumps({'steps':index,'code':os.waitstatus_to_exitcode(status),'output':buf.decode(errors='replace'),'canonical':bool(termios.tcgetattr(fd)[3]&termios.ICANON)}))
finally: os.close(fd)
`

function fixture(t) {
  if (spawnSync("python3", ["-c", "import pty"]).status !== 0) { t.skip("python3 unavailable"); return }
  const root = mkdtempSync(path.join(os.tmpdir(), "auth menu-"))
  t.after(() => rmSync(root, { recursive: true, force: true }))
  const bins = path.join(root, "bin")
  mkdirSync(bins)
  mkdirSync(path.join(root, "herdr"))
  for (const h of Object.values(HARNESSES)) writeFileSync(path.join(bins, h.bin), "#!/bin/sh\nexit 1\n", { mode: 0o755 })
  writeFileSync(path.join(bins, "claude"), `#!/usr/bin/env python3\nimport sys,json\nif sys.argv[1:]==['auth','status']:\n print(json.dumps({'loggedIn':True,'subscriptionType':'team','orgName':'E2B'}))\nelse:\n print(${JSON.stringify(REPLACEMENT)})\n`, { mode: 0o755 })
  const directory = path.join(root, "connections")
  const record = saveConnection({ id: "claude-work", harness: "claude", method: "setup-token",
    detected: classifySubscription({ subscriptionType: "team", orgName: "E2B" }) }, TOKEN, { directory })
  writeFileSync(path.join(root, "config.toml"), `[dashboard]\nconfig_opener = 'printf "%s\\n" "$1" "$2" "$PWD" > "$OPEN_CAPTURE"'\n`)
  const env = { PATH: `${bins}:${process.env.PATH}`, HOME: root, XDG_CONFIG_HOME: root, XDG_DATA_HOME: root,
    HERDR_PLUGIN_CONFIG_DIR: root, HERDR_PLUGIN_STATE_DIR: path.join(root, "state"),
    TERM: "xterm-256color", NO_COLOR: "1", SHELL: "/bin/sh", OPEN_CAPTURE: path.join(root, "opened") }
  return { root, directory, record, env }
}

function drive(f, steps) {
  const result = spawnSync("python3", ["-c", DRIVER, JSON.stringify(steps), process.execPath,
    path.join(ROOT, "src/harness-auth.js")], { env: f.env, encoding: "utf8", timeout: 30000 })
  assert.equal(result.status, 0, result.stderr)
  const observed = JSON.parse(result.stdout)
  assert.equal(observed.steps, steps.length, observed.output)
  assert.equal(observed.code, 0, observed.output)
  assert.equal(observed.canonical, true, "raw mode must be restored")
  assert.equal(observed.output.split("\x1b[?1049h").length, observed.output.split("\x1b[?1049l").length)
  assert.ok(!observed.output.includes(TOKEN))
  assert.ok(!observed.output.includes(REPLACEMENT))
  return observed.output
}

test("auth actions offer reconnect per saved account and only supported connect flows", () => {
  const connections = [{ id: "work", harness: "claude" }, { id: "personal", harness: "claude" }]
  const actions = authMenuActions("claude", connections)
  assert.deepEqual(actions.filter((a) => a.id === "reconnect").map((a) => a.connection), ["work", "personal"])
  assert.ok(actions.some((a) => a.id === "connect"))
  const droid = authMenuActions("droid", connections)
  assert.ok(!droid.some((a) => a.id === "connect" || a.id === "reconnect"))
  assert.ok(droid.some((a) => a.id === "config"))
})

