  ])
  assert.deepEqual(readFileSync(path.join(f.root, "opened"), "utf8").trim().split("\n"), [
    path.join(f.root, "herdr"), path.join(f.root, "config.toml"), realpathSync(path.join(f.root, "herdr")),
