  const f = fixture(t); if (!f) return
  drive(f, [
    { wait: "enter actions", send: "\r" },
    { wait: "Connect new claude account", send: "2" },
    { wait: "> [2]", send: "\r" },
    { wait: "New connection name", send: "claude-other\r" },
    { wait: "[y/N]", send: "y\r" },
    { wait: "Press Enter to return", send: "\r" },
    { wait: "enter actions", send: "q" },
